<template><view class="page chat"><scroll-view scroll-y class="msgs"><view v-for="(m,i) in messages" :key="i" :class="['bubble',m.role]">{{m.content}}</view></scroll-view><view class="input glass"><input v-model="text" placeholder="推荐几本人工智能入门书" @confirm="send"/><button class="btn" @click="send">发送</button></view></view></template>
<script setup>import { ref } from 'vue'; import { request } from '../../api/request'; const text=ref(''); const messages=ref([{role:'ai',content:'我是AI荐书助手，可以回答荐书、图书知识、个人阅读和后台管理问题。'}]); async function send(){if(!text.value)return; const q=text.value; messages.value.push({role:'user',content:q}); text.value=''; const r=await request('/chat/send',{method:'POST',data:{message:q}}); messages.value.push({role:'ai',content:r.answer})}</script><style scoped>.chat{display:flex;flex-direction:column;height:100vh}.msgs{flex:1}.bubble{padding:20rpx;margin:16rpx;border-radius:26rpx;background:#fff;line-height:1.6}.bubble.user{background:linear-gradient(135deg,#7c3aed,#0ea5e9);color:#fff;margin-left:120rpx}.input{display:flex;gap:12rpx;padding:18rpx}.input input{flex:1;background:#fff;border-radius:999rpx;padding:18rpx}</style>
